mapper.select:
    SELECT bu.id AS bu_id, bu.usuario_id AS usuarioId, bu.baraja_publica_id AS barajaPublicaId, bu.fecha_creacion AS fechaCreacion,
    b.id AS b_id, b.nombre AS b_nombre, b.cartas AS b_cartas
    FROM baraja_usuario bu
    JOIN baraja b ON b.id = bu.baraja_id


            AND b.cartas_nombre LIKE CONCAT('%', #{cartaNombre}, '%')


            AND bu.usuario_id = #{usuarioId}


            AND bu.baraja_publica_id = #{barajaPublicaId}




	        ORDER BY ${ordenacion}


	        ORDER BY bu.fecha_creacion DESC
